use super::*;
#[derive(Clone,Copy)]
struct OriginalPages<'a>{pages:&'a[&'a[u8]],page_bytes:usize,identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for OriginalPages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}fn byte_at(&self,index:usize)->Option<u8>{if index>=self.identity.extent{return None}self.pages.get(index/self.page_bytes)?.get(index%self.page_bytes).copied()}}
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){crate::test_allocation::observe_backing(operation)}
fn receipt(owner:&mut RetainedRecordBodySourceDecode,g:RetainedCloneGrant,born:usize,released:usize)->RetainedCloneProgress{let(issued,p)=owner.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));p}
fn hex(input:&str)->Vec<u8>{input.as_bytes().chunks_exact(2).map(|bytes|u8::from_str_radix(std::str::from_utf8(bytes).unwrap(),16).unwrap()).collect()}
fn limits(p:&serde_json::Value)->RetainedRecordBodyReadLimits{let n=|k:&str|p[k].as_u64().unwrap();RetainedRecordBodyReadLimits{pack:PackLimits{max_file_len:n("bytes"),max_segment_len:n("segmentBytes"),max_symbols:n("symbols")as u32,max_depth:n("depth")as u16,max_items:n("items"),max_total_alloc:n("totalAllocationBytes")},maximum_symbol_utf8_bytes:n("symbolUtf8Bytes")as usize,maximum_symbol_scalars:n("symbolScalars")as usize,maximum_allocation_bytes:n("allocationBytes")as usize}}
fn allocation_quote(owner:&RetainedRecordBodySourceDecode){let before=(owner.source_identity(),owner.original_range(),owner.consumed_bytes(),owner.receipt());let(quoted,born,released)=observe(||owner.allocated_bytes());assert_eq!((born,released),(0,0));assert_eq!(quoted,owner.cursor.as_ref().map_or(0,RetainedRecordBodyCursor::allocated_bytes));assert_eq!(before,(owner.source_identity(),owner.original_range(),owner.consumed_bytes(),owner.receipt()));}
#[test]
fn original_record_body_paged_source_retains_exact_grants_tokens_native_backing_and_cancelled_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|k:&str|p[k].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 let body=hex(law["source"]["bodyHex"].as_str().unwrap());let mut original=hex(law["source"]["prefixHex"].as_str().unwrap());let start=original.len();original.extend_from_slice(&body);let end=original.len();original.extend_from_slice(&hex(law["source"]["suffixHex"].as_str().unwrap()));let identity=OriginalWireSourceIdentity{address:original.as_ptr()as usize,extent:original.len(),authority:Some((law["source"]["operation"].as_u64().unwrap(),law["source"]["generation"].as_u64().unwrap()))};
 let expected:serde_json::Value=serde_json::from_str("{\"symbol\":\"漢\",\"unsigned\":127}").unwrap();assert_eq!(expected,law["expected"]);let spec=semio_framework_dsl_record::RecordSpec::new(None,semio_framework_dsl_record::RecordLayout::Inline,vec![semio_framework_dsl_record::FieldSpec::new(1,"value",semio_framework_dsl_record::Shape::UInt)]);let options=crate::record::DecodeOptions{limits:limits(&law["limits"]).pack,..Default::default()};let(decoded,_)=crate::record::decode_record_body(&body,&spec,&options).unwrap();assert_eq!(decoded.get(1),Some(&semio_framework_dsl_record::FieldValue::UInt(127)));
 for page_bytes in[original.len(),law["source"]["pageBytes"].as_u64().unwrap()as usize]{let pages=original.chunks(page_bytes).collect::<Vec<_>>();let source=OriginalPages{pages:&pages,page_bytes,identity};for cancelled in[0,1,4,20,1000]{
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g}]{let(owner,born,released)=observe(||RetainedRecordBodySourceDecode::admit(&source,(start,end),limits(&law["limits"]),denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0))}
  let(owner,born,released)=observe(||RetainedRecordBodySourceDecode::admit(&source,(start,end),limits(&law["limits"]),g).unwrap());assert_eq!((born,released),(0,0));let mut owner=owner.unwrap();assert_eq!(owner.original_range(),(start,end));assert!(!owner.terminal_is_empty());let(status,born,released)=observe(||owner.step(&source,g).unwrap());assert_eq!(status,RetainedRecordBodySourceStep::Blocked);assert_eq!((born,released),(0,0));receipt(&mut owner,g,0,0);
  for changed_identity in[OriginalWireSourceIdentity{address:identity.address+1,..identity},OriginalWireSourceIdentity{extent:identity.extent-1,..identity},OriginalWireSourceIdentity{authority:Some((43,8)),..identity}]{let changed=OriginalPages{identity:changed_identity,..source};let(result,born,released)=observe(||owner.step(&changed,g));assert!(result.is_err());assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none())}
  let(mut births,mut releases,mut copied,mut unsigned,mut chars)=(0,0,0,0,0);
  for _ in 0..cancelled{
   if owner.token().is_some(){let mut token=None;let(moved,born,released)=observe(||owner.take_token_into(&mut token,g).unwrap());assert!(moved);assert_eq!((born,released),(0,0));receipt(&mut owner,g,born,released);match token.take().unwrap(){RetainedRecordBodyToken::SymbolChar{character,..}=>{assert_eq!(character,'漢');chars+=1},RetainedRecordBodyToken::Value(RetainedValueToken::Unsigned{role:crate::record::RetainedValueRole::Unsigned,value})=>{assert_eq!(value,127);unsigned+=1},_=>{}}continue}
   allocation_quote(&owner);if owner.is_complete(){break}let demand=owner.demands(&source).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:demand.depth-1,..g},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..g}].into_iter().enumerate(){if axis==2&&demand.copy_bytes==0||axis==3&&demand.capacity_bytes==0{continue}let before=owner.consumed_bytes();let(status,born,released)=observe(||owner.step(&source,denied).unwrap());assert_eq!(status,RetainedRecordBodySourceStep::Blocked);assert_eq!((born,released),(0,0));assert_eq!(before,owner.consumed_bytes());assert!(owner.receipt().is_none())}
   let(status,born,released)=observe(||owner.step(&source,g).unwrap());assert_ne!(status,RetainedRecordBodySourceStep::Fault);let p=receipt(&mut owner,g,born,released);copied+=p.copied_bytes;births+=born;releases+=released;assert_eq!(owner.source_identity(),identity);assert_eq!(owner.original_range(),(start,end))
  }
  if cancelled==1000{assert!(owner.is_complete());assert_eq!((chars,unsigned),(1,1));assert_eq!(copied,std::mem::size_of::<char>());assert_eq!(owner.consumed_bytes(),body.len());assert_eq!(owner.symbol_chars(0).unwrap(),1);assert_eq!(owner.symbol_char(0,0).unwrap(),Some('漢'));assert_eq!(owner.symbol_utf8_bytes(0).unwrap(),3)}
  if owner.token().is_some(){let mut token=None;owner.take_token_into(&mut token,g).unwrap();receipt(&mut owner,g,0,0);drop(token)}owner.cancel();
  for _ in 0..1000{if owner.terminal_is_empty(){break}let demand=owner.close_demands().unwrap();for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:demand.depth-1,..g}),if demand.release_bytes>0{Some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..g})}else{None}].into_iter().flatten(){let(status,born,released)=observe(||owner.close_step(denied).unwrap());assert_eq!(status,RetainedRecordBodySourceStep::Blocked);assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none())}let(status,born,released)=observe(||owner.close_step(g).unwrap());assert_ne!(status,RetainedRecordBodySourceStep::Blocked);assert_eq!(receipt(&mut owner,g,born,released).copied_bytes,0);births+=born;releases+=released}
  assert!(owner.terminal_is_empty());allocation_quote(&owner);assert_eq!(owner.allocated_bytes(),0);assert_eq!(births,releases);let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));
 }}
 eprintln!("[DEBUG] Original RecordBody paged/contiguous source and ranged tokens retain actual sealed authority; independently fixed17 full5 denies before mutation, paid real token recipients and actual native cursor/symbol/stack birth-release conserve every original owner and terminalDrop0");
}
